package dev.aura.player;
import static org.junit.Assert.*;import org.junit.*;import org.junit.runner.RunWith;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;
import android.content.*;import android.net.Uri;import android.provider.DocumentsContract;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;

@RunWith(AndroidJUnit4.class)
public class IncrementalLibraryTest {
    final Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();final Uri provider=Uri.parse("content://dev.aura.player.test.documents");
    @After public void cleanup(){DriveLibrary.clear(c);DriveAuth.get(c).clear();c.getContentResolver().call(provider,"test.reset",null,null);}
    @Test public void localUnknownDatesAndIncompleteTagsNeverReopenExistingSongs()throws Exception{c.getContentResolver().call(provider,"test.reset",null,null);c.getContentResolver().call(provider,"test.unknown",null,null);File cache=new File(c.getFilesDir(),"library-metadata.json");cache.delete();var library=new Library(c);List<Uri> roots=List.of(DocumentsContract.buildTreeDocumentUri(provider.getAuthority(),"A"),DocumentsContract.buildTreeDocumentUri(provider.getAuthority(),"B"));library.scan(roots,p->{});File index=new File(c.getFilesDir(),"library.json");JSONArray rows=new JSONArray(new String(Files.readAllBytes(index.toPath()),StandardCharsets.UTF_8));for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).getString("uri").contains("c.wav"))rows.getJSONObject(i).put("duration",0).put("title","Keep my existing tags");Files.write(index.toPath(),rows.toString().getBytes(StandardCharsets.UTF_8));String before=new String(Files.readAllBytes(index.toPath()),StandardCharsets.UTF_8);var stats=c.getContentResolver().call(provider,"test.stats",null,null);long revision=Library.revision;library.scan(roots,p->{},true);assertEquals(stats.getInt("opens"),c.getContentResolver().call(provider,"test.stats",null,null).getInt("opens"));assertEquals(before,new String(Files.readAllBytes(index.toPath()),StandardCharsets.UTF_8));assertEquals(revision,Library.revision);c.getContentResolver().call(provider,"test.change",null,null);var updated=library.scan(roots,p->{},true);var after=c.getContentResolver().call(provider,"test.stats",null,null);assertEquals(stats.getInt("open:A/sub/b.wav"),after.getInt("open:A/sub/b.wav"));assertEquals(stats.getInt("open:B/c.wav"),after.getInt("open:B/c.wav"));assertTrue(after.getInt("open:A/new.wav")>0);assertEquals(3,updated.size());assertFalse(updated.stream().anyMatch(t->t.uri.contains("a.wav")));assertTrue(updated.stream().anyMatch(t->t.uri.contains("new.wav")));assertTrue(updated.stream().anyMatch(t->t.title.equals("Keep my existing tags")&&t.duration==0));}
    @Test public void driveFeedListsOnlyDirtyFoldersAndReadsOnlyNewSongs()throws Exception{try(Server server=new Server()){var counter=new AtomicInteger();var library=cloud(server,counter);library.scan(p->{});assertEquals(3,counter.get());library.scan(p->{},true);assertEquals("Migration must not retry missing tags/art",3,counter.get());server.listings.clear();long revision=DriveLibrary.revision;library.scan(p->{},true);assertTrue(server.listings.isEmpty());assertEquals(3,counter.get());assertEquals(revision,DriveLibrary.revision);server.files.put("root",new JSONArray().put(folder("sub")).put(folder("quiet")).put(audio("a","Renamed.wav")).put(audio("new","New.wav")));server.files.put("sub",new JSONArray());server.feed=new JSONArray().put(change("a","root",false)).put(change("new","root",false)).put(new JSONObject().put("fileId","b").put("removed",true));var songs=library.scan(p->{},true);assertEquals(4,counter.get());assertEquals(3,songs.size());assertTrue(songs.stream().anyMatch(t->t.title.equals("Tagged a")));assertFalse(songs.stream().anyMatch(t->t.title.equals("Tagged b")));assertTrue(songs.stream().anyMatch(t->t.title.equals("Tagged new")));assertEquals(1,Collections.frequency(server.listings,"root"));assertEquals(1,Collections.frequency(server.listings,"sub"));assertFalse(server.listings.contains("quiet"));server.feed=new JSONArray();server.listings.clear();library.scan(p->{},true);assertTrue(server.listings.isEmpty());assertEquals(4,counter.get());assertEquals(0,server.audioRequests.get());}}
    @Test public void failedFeedPageCannotAdvanceCursorOrReplaceLibrary()throws Exception{try(Server server=new Server()){var library=cloud(server,new AtomicInteger());library.scan(p->{},true);File index=new File(c.getFilesDir(),"drive-library.json");String previous=new String(Files.readAllBytes(index.toPath()),StandardCharsets.UTF_8);server.failNextPage=true;try{library.scan(p->{},true);fail("Expected failed change page");}catch(IOException expected){}assertEquals(previous,new String(Files.readAllBytes(index.toPath()),StandardCharsets.UTF_8));}}
    private DriveLibrary cloud(Server server,AtomicInteger count)throws Exception{DriveLibrary.clear(c);DriveAuth.get(c).accept("incremental-test","fake@example.invalid","테스트","fake-token");DriveLibrary.saveRoots(c,List.of(new DriveLibrary.Folder("root","Music")));return new DriveLibrary(c,new DriveApi(new DriveHttp(server.base(),new DriveHttp.Tokens(){public String token(){return "fake";}public void invalidate(String token){}})),(context,row,generation)->{count.incrementAndGet();String id=DriveUris.fileId(Uri.parse(row.getString("uri")));return new JSONObject(row.toString()).put("title","Tagged "+id).put("duration",0).put("enriched",false).put("art",true).put("artKind","embedded");});}
    static JSONObject audio(String id,String name)throws Exception{return new JSONObject().put("id",id).put("name",name).put("mimeType","audio/wav").put("size",1000).put("modifiedTime","2026-10-27");}static JSONObject folder(String id)throws Exception{return new JSONObject().put("id",id).put("name",id).put("mimeType",DriveApi.FOLDER);}static JSONObject change(String id,String parent,boolean removed)throws Exception{return new JSONObject().put("fileId",id).put("removed",removed).put("file",new JSONObject().put("id",id).put("parents",new JSONArray().put(parent)));}
    static final class Server implements AutoCloseable {final ServerSocket socket=new ServerSocket(0,50,InetAddress.getByName("127.0.0.1"));final ExecutorService workers=Executors.newCachedThreadPool();final Map<String,JSONArray> files=new ConcurrentHashMap<>();final List<String> listings=new CopyOnWriteArrayList<>();final AtomicInteger audioRequests=new AtomicInteger();volatile JSONArray feed=new JSONArray();volatile boolean failNextPage;volatile String failedFolder="";
        Server()throws Exception{files.put("root",new JSONArray().put(folder("sub")).put(folder("quiet")).put(audio("a","A.wav")));files.put("sub",new JSONArray().put(audio("b","B.wav")));files.put("quiet",new JSONArray().put(audio("d","D.wav")));workers.execute(()->{while(!socket.isClosed())try{Socket s=socket.accept();workers.execute(()->serve(s));}catch(IOException ignored){}});}
        String base(){return "http://127.0.0.1:"+socket.getLocalPort()+"/drive/v3/";}
        void serve(Socket client){try(client){BufferedReader in=new BufferedReader(new InputStreamReader(client.getInputStream(),StandardCharsets.UTF_8));String first=in.readLine(),line;if(first==null)return;while((line=in.readLine())!=null&&!line.isEmpty()){}String path=URLDecoder.decode(first.split(" ")[1],"UTF-8"),body;int status=200;if(path.contains("alt=media")){audioRequests.incrementAndGet();body="{}";}else if(path.contains("startPageToken"))body="{\"startPageToken\":\"base\"}";else if(path.contains("/changes?")){if(path.contains("pageToken=broken")){status=503;body="{}";}else if(failNextPage)body="{\"changes\":[],\"nextPageToken\":\"broken\"}";else body=new JSONObject().put("changes",feed).put("newStartPageToken","after").toString();}else{String parent="root";for(String id:files.keySet())if(path.contains("'"+id+"'"))parent=id;listings.add(parent);if(!failedFolder.isEmpty()&&path.contains("'"+failedFolder+"'")){status=503;body="{}";}else body=new JSONObject().put("files",files.get(parent)).toString();}byte[] bytes=body.getBytes(StandardCharsets.UTF_8);OutputStream out=client.getOutputStream();out.write(("HTTP/1.1 "+status+" Test\r\nContent-Length: "+bytes.length+"\r\nContent-Type: application/json\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(bytes);}catch(Exception ignored){}}
        public void close()throws IOException{socket.close();workers.shutdownNow();}
    }
}
